settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap');
.mfp.mfp-kfb.mfp-native-generated {--kfb-primary:#E8607A;--kfb-accent:#4A90D9;--kfb-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--kfb-text:var(--mf-page-text,var(--mf-preset-text,#5A3A4A));--kfb-muted:var(--mf-page-muted,var(--mf-preset-muted,#B09AA8));--kfb-border:var(--mf-page-border,var(--mf-preset-border,#F0C8D8));--kfb-on-primary:var(--mf-preset-on-primary,#FFFFFF);--kfb-deco:#FDEEA0;--kfb-page:#FDF0F4;--kfb-fill:#FDF0F4;--kfb-fill-strong:color-mix(in srgb, var(--kfb-text) 9%, var(--kfb-surface));--kfb-soft:color-mix(in srgb, var(--kfb-primary) 12%, var(--kfb-surface));--kfb-hairline:color-mix(in srgb, var(--kfb-text) 12%, var(--kfb-surface));}.mfp.mfp-kfb.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'Nunito',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-kfb.mfp-native-generated {--kfb-primary:var(--mf-page-primary,var(--mf-preset-primary,#E8607A));--kfb-accent:var(--mf-page-accent,var(--mf-preset-accent,#4A90D9));--kfb-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--kfb-text:var(--mf-page-text,var(--mf-preset-text,#5A3A4A));--kfb-border:var(--mf-page-border,var(--mf-preset-border,#F0C8D8));--kfb-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FFFFFF));--kfb-page:var(--mf-preset-bg,#FDF0F4);}@container (max-width:520px){.mfp.mfp-kfb.mfp-native-generated [class*="-grid"],.mfp.mfp-kfb.mfp-native-generated [class*="-meta"],.mfp.mfp-kfb.mfp-native-generated [class*="-scores"],.mfp.mfp-kfb.mfp-native-generated [class*="-charts"],.mfp.mfp-kfb.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-kfb.mfp-native-generated [class*="-body"],.mfp.mfp-kfb.mfp-native-generated [class*="-split"],.mfp.mfp-kfb.mfp-native-generated [class*="-foot"],.mfp.mfp-kfb.mfp-native-generated [class*="-head"],.mfp.mfp-kfb.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-kfb.mfp-native-generated [class*="-aside"],.mfp.mfp-kfb.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-kfb.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-kfb.mfp-native-generated {overflow-wrap:break-word}
.mfp.mfp-kfb.mfp-native-generated {font-family:'Nunito',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--kfb-text)}
.mfp.mfp-kfb.mfp-native-generated .kfb-page{padding:40px 16px;background:var(--kfb-page)}
.mfp.mfp-kfb.mfp-native-generated .kfb-shell{max-width:672px;margin:0 auto}
.mfp.mfp-kfb.mfp-native-generated .kfb-card{position:relative;overflow:hidden;border:4px dashed #B5EAD7;border-radius:24px;
  background:#fff;box-shadow:0 25px 50px -12px rgba(0,0,0,.25)}

/* gingham banner: a 20px pattern of two 10px squares at 18% white ------- */
.mfp.mfp-kfb.mfp-native-generated .kfb-banner{position:relative;overflow:hidden;padding:32px 32px 24px;background:#F9C8D4;
  background-image:linear-gradient(45deg,rgba(255,255,255,.18) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.18) 75%),
    linear-gradient(45deg,rgba(255,255,255,.18) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.18) 75%);
  background-size:20px 20px;background-position:0 0,10px 10px}
.mfp.mfp-kfb.mfp-native-generated .kfb-star{position:absolute;color:#FDEEA0}
.mfp.mfp-kfb.mfp-native-generated .kfb-star-a{top:16px;right:40px;font-size:20px}
.mfp.mfp-kfb.mfp-native-generated .kfb-star-b{top:32px;right:24px;font-size:12px;opacity:.7}
.mfp.mfp-kfb.mfp-native-generated .kfb-star-c{top:12px;left:24px;font-size:16px;opacity:.5}
.mfp.mfp-kfb.mfp-native-generated .kfb-unicorn{position:absolute;right:24px;bottom:-24px;width:112px;height:112px;
  background-image:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 120 120'%3E %3Cellipse cx='60' cy='78' rx='30' ry='22' fill='%23FDEAF0'%2F%3E %3Ccircle cx='85' cy='58' r='18' fill='%23FDEAF0'%2F%3E %3Cpolygon points='90,44 86,24 94,40' fill='%23F4C542'%2F%3E %3Cpolygon points='78,44 74,34 84,42' fill='%23F9A8C4'%2F%3E %3Ccircle cx='89' cy='57' r='3' fill='%235A3A4A'%2F%3E%3Ccircle cx='90' cy='56' r='1' fill='white'%2F%3E %3Ccircle cx='98' cy='62' r='1.5' fill='%23F4829E'%2F%3E %3Cpath d='M78 46 Q70 55 72 65 Q65 58 70 48 Q65 54 68 63 Q60 56 65 44' fill='none' stroke='%23C8A0F0' stroke-width='3' stroke-linecap='round'%2F%3E %3Cpath d='M80 45 Q74 52 76 60' fill='none' stroke='%23F9A8C4' stroke-width='2.5' stroke-linecap='round'%2F%3E %3Crect x='40' y='96' width='8' height='16' rx='4' fill='%23FDEAF0'%2F%3E %3Crect x='54' y='96' width='8' height='16' rx='4' fill='%23FDEAF0'%2F%3E %3Crect x='68' y='96' width='8' height='14' rx='4' fill='%23FDEAF0'%2F%3E %3Crect x='82' y='94' width='8' height='14' rx='4' fill='%23FDEAF0'%2F%3E %3Cpath d='M32 72 Q18 80 20 95 Q28 85 30 92' fill='none' stroke='%23C8A0F0' stroke-width='3.5' stroke-linecap='round'%2F%3E %3Cpath d='M33 74 Q16 86 22 100' fill='none' stroke='%23F9A8C4' stroke-width='2.5' stroke-linecap='round'%2F%3E %3Cpath d='M34 76 Q20 90 25 104' fill='none' stroke='%23FDEEA0' stroke-width='2' stroke-linecap='round'%2F%3E %3C%2Fsvg%3E");background-size:contain;background-repeat:no-repeat}
.mfp.mfp-kfb.mfp-native-generated .kfb-stars{display:flex;justify-content:center;gap:12px;margin-top:24px}
.mfp.mfp-kfb.mfp-native-generated .kfb-stars i{font-size:20px;line-height:20px}
.mfp.mfp-kfb.mfp-native-generated .kfb-s0{color:#F4829E}
.mfp.mfp-kfb.mfp-native-generated .kfb-s1{color:#7DD4B8}
.mfp.mfp-kfb.mfp-native-generated .kfb-s2{color:#FDEEA0}
.mfp.mfp-kfb.mfp-native-generated .kfb-s3{color:var(--kfb-accent)}
.mfp.mfp-kfb.mfp-native-generated .kfb-s4{color:var(--kfb-primary)}
.mfp.mfp-kfb.mfp-native-generated h1.kfb-h1{position:relative;margin:0!important;text-align:center!important;font-size:36px!important;
  line-height:1.25!important;font-weight:900!important;letter-spacing:.025em!important;
  color:var(--kfb-primary)!important}
.mfp.mfp-kfb.mfp-native-generated p.kfb-sub{position:relative;margin:4px 0 0!important;text-align:center!important;
  font-size:14px!important;line-height:20px!important;font-weight:600!important;color:#C0607A!important}

/* body, full-bleed section bands ---------------------------------------- */
.mfp.mfp-kfb.mfp-native-generated .kfb-body{padding:24px 32px 32px}
.mfp.mfp-kfb.mfp-native-generated .kfb-band{margin:16px -32px;padding:8px 32px}
.mfp.mfp-kfb.mfp-native-generated .kfb-band-t{font-size:12px;line-height:16px;font-weight:900;letter-spacing:.18em;
  text-transform:uppercase;color:var(--kfb-text)}
.mfp.mfp-kfb.mfp-native-generated .kfb-band-mint{background:#B5EAD7}
.mfp.mfp-kfb.mfp-native-generated .kfb-band-sky{background:#A8D8EA}
.mfp.mfp-kfb.mfp-native-generated .kfb-band-yellow{background:#FDEEA0}
.mfp.mfp-kfb.mfp-native-generated .kfb-band-pink{background:#F9C8D4}

/* one field per line, fixed label column -------------------------------- */
.mfp.mfp-kfb.mfp-native-generated .kfb-row{display:flex;align-items:center;gap:12px;margin:0;padding:6px 0;
  border-bottom:1px solid #F5E0E8}
.mfp.mfp-kfb.mfp-native-generated .kfb-row-l{flex:0 0 150px;width:150px;font-size:11px;line-height:16px;font-weight:900;
  letter-spacing:.12em;text-transform:uppercase;color:#C0708A}
.mfp.mfp-kfb.mfp-native-generated .kfb-row-c{flex:1 1 auto;min-width:0;display:block}
.mfp.mfp-kfb.mfp-native-generated .kfb-chips{padding:12px 0}
.mfp.mfp-kfb.mfp-native-generated .kfb-ta{padding:12px 0}
.mfp.mfp-kfb.mfp-native-generated .kfb-cta{padding-top:16px}
.mfp.mfp-kfb.mfp-native-generated .kfb-back{padding-top:16px;text-align:center}
.mfp.mfp-kfb.mfp-native-generated .kfb-back-link{display:inline-flex;align-items:center;gap:6px;font-size:14px;line-height:20px;
  font-weight:600;color:#B09AA8}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-kfb.mfp-native-generated label,.mfp.mfp-kfb.mfp-native-generated span,.mfp.mfp-kfb.mfp-native-generated p,.mfp.mfp-kfb.mfp-native-generated div,.mfp.mfp-kfb.mfp-native-generated ul,.mfp.mfp-kfb.mfp-native-generated li,.mfp.mfp-kfb.mfp-native-generated h1,.mfp.mfp-kfb.mfp-native-generated h2,.mfp.mfp-kfb.mfp-native-generated h3,.mfp.mfp-kfb.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-kfb.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-kfb.mfp-native-generated .mf-section-break,.mfp.mfp-kfb.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-kfb.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-kfb.mfp-native-generated .mf-form-title,.mfp.mfp-kfb.mfp-native-generated .mf-form-description,.mfp.mfp-kfb.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-kfb.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-kfb.mfp-native-generated .mf-input[class],.mfp.mfp-kfb.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:0!important;border-bottom:2px solid #F4B8C8!important;border-radius:0!important;
  background:transparent!important;padding:6px 0!important;min-height:0!important;
  height:auto!important;color:var(--kfb-text)!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;font-weight:400!important;
  box-shadow:none!important;appearance:none!important;-webkit-appearance:none!important}
.mfp.mfp-kfb.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-kfb.mfp-native-generated .mf-select[class]:focus{border-bottom-color:#F4829E!important;
  box-shadow:none!important;outline:none!important}
.mfp.mfp-kfb.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-kfb.mfp-native-generated .mf-textarea[class]::placeholder{color:#B09AA8!important;opacity:1}
/* :invalid only fires on a REQUIRED select; :has() covers the optional ones too. */
.mfp.mfp-kfb.mfp-native-generated .mf-select[class]:invalid,
.mfp.mfp-kfb.mfp-native-generated .mf-select[class]:has(option[value=""]:checked){color:#B09AA8!important}

/* the rule under a control is DOTTED here, not solid */
.mfp.mfp-kfb.mfp-native-generated .mf-input[class],.mfp.mfp-kfb.mfp-native-generated .mf-select[class]{border-bottom-style:dotted!important;font-weight:600!important}
.mfp.mfp-kfb.mfp-native-generated .mf-textarea[class]{width:100%!important;box-sizing:border-box!important;
  border:2px dashed var(--kfb-border)!important;border-radius:16px!important;background:#FFFBFC!important;
  padding:16px!important;min-height:96px!important;height:96px!important;resize:none!important;
  color:var(--kfb-text)!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:600!important;box-shadow:none!important}

/* interest pills --------------------------------------------------------- */
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips{display:flex;flex-wrap:wrap;gap:8px}
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips .mf-option-ui{display:block;gap:0;padding:6px 16px;
  border:2px solid var(--kfb-border);border-radius:9999px;background:#fff;color:var(--kfb-text);font-size:14px;
  line-height:20px;font-weight:700;text-align:center;cursor:pointer;transition:all .15s ease}
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips .mf-option-label{font-size:14px;line-height:20px;font-weight:700;
  color:inherit}
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-kfb.mfp-native-generated .mf-option-group--chips input:checked+.mf-option-ui{background:#F4829E;border-color:var(--kfb-primary);
  color:#fff}

/* declaration, CTA ------------------------------------------------------- */
.mfp.mfp-kfb.mfp-native-generated .kfb-consent{display:flex;flex-direction:column;gap:12px;padding:12px 0}
.mfp.mfp-kfb.mfp-native-generated .kfb-consent .mf-option-group--list{display:flex;flex-direction:column;gap:12px}
.mfp.mfp-kfb.mfp-native-generated .kfb-consent .mf-option-item{display:flex;align-items:flex-start;gap:12px}
.mfp.mfp-kfb.mfp-native-generated .kfb-consent .mf-option-ui{display:block;padding:0;border:0;background:transparent}
.mfp.mfp-kfb.mfp-native-generated .kfb-consent .mf-option-label{font-size:14px;line-height:20px;font-weight:600;color:var(--kfb-text)}
.mfp.mfp-kfb.mfp-native-generated .kfb-consent input[type="checkbox"]{width:20px!important;height:20px!important;
  flex:0 0 20px!important;margin:1px 0 0!important;border:2px solid #F4B8C8!important;
  border-radius:6px!important}
.mfp.mfp-kfb.mfp-native-generated .kfb-link{text-decoration:underline;font-weight:700;color:var(--kfb-primary)}
.mfp.mfp-kfb.mfp-native-generated button.kfb-submit[type="submit"]{display:block;width:100%!important;padding:16px 0!important;
  border:0!important;border-radius:16px!important;background:var(--kfb-accent)!important;color:#fff!important;
  font-family:inherit!important;font-size:16px!important;line-height:24px!important;
  font-weight:900!important;letter-spacing:.1em!important;text-transform:uppercase!important;
  cursor:pointer!important;box-shadow:none!important}
/* the mock's CTA is never greyed - it validates on click */
.mfp.mfp-kfb.mfp-native-generated button.kfb-submit.mf-nav-blocked,.mfp.mfp-kfb.mfp-native-generated button.kfb-submit[disabled]{opacity:1!important;
  background:var(--kfb-accent)!important;cursor:not-allowed!important;filter:none!important}
.mfp.mfp-kfb.mfp-native-generated .kfb-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-kfb.mfp-native-generated .kfb-shell,.mfp.mfp-kfb.mfp-native-generated .kfb-wrap{max-width:none!important;margin:0!important}.mfp.mfp-kfb.mfp-native-generated .kfb-grid,.mfp.mfp-kfb.mfp-native-generated .kfb-main,.mfp.mfp-kfb.mfp-native-generated .kfb-hero-in,.mfp.mfp-kfb.mfp-native-generated .kfb-card{max-width:none!important;margin-left:0!important;margin-right:0!important}
